-- V23 — outbound dispatch, capture forms + bay dashboard + camera + PMT-as-form.
-- Turns the 'status-flip, records nothing' step pages into queue → capture-form →
-- submit pages (the proven Dispatch pattern): QC Pre-Load, Supervisor Assign,
-- Sealing, Billing, Weight-Diff, PMT and Camera now capture the operator's data
-- (supervisor, location, seal no, invoice, reason, weights) which the workflow
-- projection already persists to gate_pass. Adds the bay-wise Loading Dashboard.
-- Idempotent: page-body UPDATEs overwrite; the new page uses INSERT ... NOT EXISTS.

-- new dashboard page
INSERT INTO page_definition (tenant_id, code, title, category, description, status)
SELECT -1,'aria:loading-dashboard','Loading Dashboard (Bay-wise)','M10','Live bay-wise view of vehicles currently loading — bay, vehicle, order, processed vs remaining qty.','PUBLISHED'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM page_definition WHERE code='aria:loading-dashboard');

-- capture-form page bodies
UPDATE page_version pv JOIN page_definition pd ON pd.current_version_id=pv.id SET pv.body_json='{"kind": "layout", "schemaVersion": 2, "entity": "GatePass", "dataSources": [{"id": "q", "kind": "rest", "method": "GET", "url": "/api/workflow/queue/QC"}], "layout": [{"kind": "Grid", "columns": 12, "gap": 16, "children": [{"kind": "Section", "title": "QC Pre-Load — Queue", "span": 12, "subtitle": "Vehicles awaiting QC pre-load approval. Approve records the loading supervisor + location; Reject needs a reason.", "children": [{"kind": "WorkflowQueueList", "persona": "QC", "dataSource": "q", "pageSize": 25, "cardFields": ["gpNumber", "vehicleNo", "flowVariant", "currentState"]}]}, {"kind": "Section", "title": "Capture & Submit", "span": 12, "children": [{"kind": "Form", "bindings": {"fields": [{"name": "gpNumber", "label": "Gate Pass # (pick one)", "type": "select", "required": true, "optionsSource": {"type": "entity", "entity": "GatePass", "lookupType": "gpNumbers", "valueField": "gp_number", "labelField": "gp_number"}, "onChangeFill": {"vehicle_no": "vehicle_no", "flow_variant_code": "flow_variant_code", "instanceId": "workflow_instance_id"}}, {"name": "vehicle_no", "label": "Vehicle", "type": "text", "readOnly": true}, {"name": "flow_variant_code", "label": "Flow", "type": "text", "readOnly": true}, {"name": "loading_supervisor", "label": "Loading Supervisor", "type": "text", "visibleWhen": "#form.flow_variant_code == \'M10.TankerOutbound\'"}, {"name": "loading_tank_location", "label": "Loading Location", "type": "text"}, {"name": "qc_reject_reason", "label": "Reject Reason (only if rejecting)", "type": "textarea"}]}, "children": [{"kind": "WorkflowActionButton", "label": "Approve", "action": "workflow.transition", "instanceId": "{{form.instanceId}}", "targetState": "QC_PRELOAD_APPROVED", "color": "primary"}, {"kind": "WorkflowActionButton", "label": "Reject", "action": "workflow.transition", "instanceId": "{{form.instanceId}}", "targetState": "QC_PRELOAD_REJECTED", "color": "error"}]}]}]}]}' WHERE pd.code='aria:qc-preload-approval';
UPDATE page_version pv JOIN page_definition pd ON pd.current_version_id=pv.id SET pv.body_json='{"kind": "layout", "schemaVersion": 2, "entity": "GatePass", "dataSources": [{"id": "q", "kind": "rest", "method": "GET", "url": "/api/workflow/queue/Dispatch"}], "layout": [{"kind": "Grid", "columns": 12, "gap": 16, "children": [{"kind": "Section", "title": "Loading Supervisor Assign — Queue", "span": 12, "subtitle": "Vehicles approved by QC, awaiting a loading supervisor.", "children": [{"kind": "WorkflowQueueList", "persona": "Dispatch", "dataSource": "q", "pageSize": 25, "cardFields": ["gpNumber", "vehicleNo", "flowVariant", "currentState"]}]}, {"kind": "Section", "title": "Capture & Submit", "span": 12, "children": [{"kind": "Form", "bindings": {"fields": [{"name": "gpNumber", "label": "Gate Pass # (pick one)", "type": "select", "required": true, "optionsSource": {"type": "entity", "entity": "GatePass", "lookupType": "gpNumbers", "valueField": "gp_number", "labelField": "gp_number"}, "onChangeFill": {"vehicle_no": "vehicle_no", "flow_variant_code": "flow_variant_code", "instanceId": "workflow_instance_id"}}, {"name": "vehicle_no", "label": "Vehicle", "type": "text", "readOnly": true}, {"name": "flow_variant_code", "label": "Flow", "type": "text", "readOnly": true}, {"name": "supervisor_name", "label": "Supervisor Name", "type": "text", "required": true}]}, "children": [{"kind": "WorkflowActionButton", "label": "Assign Supervisor", "action": "workflow.transition", "instanceId": "{{form.instanceId}}", "targetState": "LOADING_ALLOCATED", "color": "primary"}]}]}]}]}' WHERE pd.code='aria:loading-allocation';
UPDATE page_version pv JOIN page_definition pd ON pd.current_version_id=pv.id SET pv.body_json='{"kind": "layout", "schemaVersion": 2, "entity": "GatePass", "dataSources": [{"id": "q", "kind": "rest", "method": "GET", "url": "/api/workflow/queue/Dispatch"}], "layout": [{"kind": "Grid", "columns": 12, "gap": 16, "children": [{"kind": "Section", "title": "Sealing — Queue", "span": 12, "subtitle": "Loaded vehicles awaiting sealing (packing / FG). Record the seal number.", "children": [{"kind": "WorkflowQueueList", "persona": "Dispatch", "dataSource": "q", "pageSize": 25, "cardFields": ["gpNumber", "vehicleNo", "flowVariant", "currentState"]}]}, {"kind": "Section", "title": "Capture & Submit", "span": 12, "children": [{"kind": "Form", "bindings": {"fields": [{"name": "gpNumber", "label": "Gate Pass # (pick one)", "type": "select", "required": true, "optionsSource": {"type": "entity", "entity": "GatePass", "lookupType": "gpNumbers", "valueField": "gp_number", "labelField": "gp_number"}, "onChangeFill": {"vehicle_no": "vehicle_no", "flow_variant_code": "flow_variant_code", "instanceId": "workflow_instance_id"}}, {"name": "vehicle_no", "label": "Vehicle", "type": "text", "readOnly": true}, {"name": "flow_variant_code", "label": "Flow", "type": "text", "readOnly": true}, {"name": "sealing_no", "label": "Sealing No", "type": "text", "required": true}, {"name": "sealing_supervisor", "label": "Sealing Supervisor", "type": "text"}, {"name": "seal_lock_status", "label": "Sealing Status", "type": "select", "options": [{"label": "Completed", "value": "AUTO_LOCK"}, {"label": "Seal No Updated", "value": "SEAL_NO_UPDATE"}]}]}, "children": [{"kind": "WorkflowActionButton", "label": "Sealing Done", "action": "workflow.transition", "instanceId": "{{form.instanceId}}", "targetState": "SEALING_DONE", "color": "primary"}]}]}]}]}' WHERE pd.code='aria:sealing-process';
UPDATE page_version pv JOIN page_definition pd ON pd.current_version_id=pv.id SET pv.body_json='{"kind": "layout", "schemaVersion": 2, "entity": "GatePass", "dataSources": [{"id": "q", "kind": "rest", "method": "GET", "url": "/api/workflow/queue/Dispatch"}], "layout": [{"kind": "Grid", "columns": 12, "gap": 16, "children": [{"kind": "Section", "title": "Billing — Queue", "span": 12, "subtitle": "Vehicles cleared by PMT, awaiting billing. Record the invoice.", "children": [{"kind": "WorkflowQueueList", "persona": "Dispatch", "dataSource": "q", "pageSize": 25, "cardFields": ["gpNumber", "vehicleNo", "flowVariant", "currentState"]}]}, {"kind": "Section", "title": "Capture & Submit", "span": 12, "children": [{"kind": "Form", "bindings": {"fields": [{"name": "gpNumber", "label": "Gate Pass # (pick one)", "type": "select", "required": true, "optionsSource": {"type": "entity", "entity": "GatePass", "lookupType": "gpNumbers", "valueField": "gp_number", "labelField": "gp_number"}, "onChangeFill": {"vehicle_no": "vehicle_no", "flow_variant_code": "flow_variant_code", "instanceId": "workflow_instance_id", "reference_no": "reference_no", "dispatch_qty": "dispatch_qty"}}, {"name": "vehicle_no", "label": "Vehicle", "type": "text", "readOnly": true}, {"name": "reference_no", "label": "Order ID", "type": "text", "readOnly": true}, {"name": "dispatch_qty", "label": "Loading Qty", "type": "text", "readOnly": true}, {"name": "invoice_no", "label": "Invoice Number", "type": "text", "required": true}, {"name": "checking_officer", "label": "Billing Officer", "type": "text"}]}, "children": [{"kind": "WorkflowActionButton", "label": "Billing Done", "action": "workflow.transition", "instanceId": "{{form.instanceId}}", "targetState": "BILLING_DONE", "color": "primary"}]}]}]}]}' WHERE pd.code='aria:billing-entry';
UPDATE page_version pv JOIN page_definition pd ON pd.current_version_id=pv.id SET pv.body_json='{"kind": "layout", "schemaVersion": 2, "entity": "GatePass", "dataSources": [{"id": "q", "kind": "rest", "method": "GET", "url": "/api/workflow/queue/PMT"}], "layout": [{"kind": "Grid", "columns": 12, "gap": 16, "children": [{"kind": "Section", "title": "OrderApp vs Loading Weight — Queue", "span": 12, "subtitle": "Compare 2nd/3rd weight; if there\'s a difference, record the reason.", "children": [{"kind": "WorkflowQueueList", "persona": "PMT", "dataSource": "q", "pageSize": 25, "cardFields": ["gpNumber", "vehicleNo", "flowVariant", "currentState"]}]}, {"kind": "Section", "title": "Capture & Submit", "span": 12, "children": [{"kind": "Form", "bindings": {"fields": [{"name": "gpNumber", "label": "Gate Pass # (pick one)", "type": "select", "required": true, "optionsSource": {"type": "entity", "entity": "GatePass", "lookupType": "gpNumbers", "valueField": "gp_number", "labelField": "gp_number"}, "onChangeFill": {"vehicle_no": "vehicle_no", "flow_variant_code": "flow_variant_code", "instanceId": "workflow_instance_id", "w2_weight_kg": "w2_weight_kg"}}, {"name": "vehicle_no", "label": "Vehicle", "type": "text", "readOnly": true}, {"name": "w2_weight_kg", "label": "2nd Weight (kg)", "type": "text", "readOnly": true}, {"name": "w3_weight_kg", "label": "3rd Weight (kg)", "type": "number"}, {"name": "variance_reason", "label": "Weight Difference Reason", "type": "textarea"}]}, "children": [{"kind": "WorkflowActionButton", "label": "Weight OK", "action": "workflow.transition", "instanceId": "{{form.instanceId}}", "targetState": "WEIGHT_DIFF_OK", "color": "primary"}, {"kind": "WorkflowActionButton", "label": "Needs Manager", "action": "workflow.transition", "instanceId": "{{form.instanceId}}", "targetState": "WEIGHT_DIFF_PENDING_MANAGER", "color": "warning"}]}]}]}]}' WHERE pd.code='aria:weight-diff-entry';

-- PMT-as-form + camera bodies
UPDATE page_version pv JOIN page_definition pd ON pd.current_version_id=pv.id SET pv.body_json='{"kind": "layout", "schemaVersion": 2, "entity": "GatePass", "dataSources": [{"id": "q", "kind": "rest", "method": "GET", "url": "/api/workflow/queue/PMT"}], "layout": [{"kind": "Grid", "columns": 12, "gap": 16, "children": [{"kind": "Section", "title": "PMT — Pending Verification", "span": 12, "subtitle": "OrderApp qty vs loading qty. Tolerance 4 kg / ton (0.4%). Over-tolerance → camera + manager reason.", "children": [{"kind": "WorkflowQueueList", "persona": "PMT", "dataSource": "q", "pageSize": 25, "cardFields": ["gpNumber", "vehicleNo", "flowVariant", "currentState"]}]}, {"kind": "Section", "title": "Verify", "span": 12, "children": [{"kind": "Form", "bindings": {"fields": [{"name": "gpNumber", "label": "Gate Pass # (pick one)", "type": "select", "required": true, "optionsSource": {"type": "entity", "entity": "GatePass", "lookupType": "gpNumbers", "valueField": "gp_number", "labelField": "gp_number"}, "onChangeFill": {"vehicle_no": "vehicle_no", "instanceId": "workflow_instance_id", "w1_weight_kg": "w1_weight_kg", "w2_weight_kg": "w2_weight_kg", "ordered_qty": "ordered_qty", "reference_no": "reference_no"}}, {"name": "vehicle_no", "label": "Vehicle", "type": "text", "readOnly": true}, {"name": "reference_no", "label": "Order ID", "type": "text", "readOnly": true}, {"name": "w1_weight_kg", "label": "1st Weight (kg)", "type": "text", "readOnly": true}, {"name": "w2_weight_kg", "label": "2nd Weight (kg)", "type": "text", "readOnly": true}, {"name": "ordered_qty", "label": "OrderApp Qty", "type": "text", "readOnly": true}, {"name": "variance_reason", "label": "Variance Reason (required if over tolerance / to manager)", "type": "textarea"}]}, "children": [{"kind": "WorkflowActionButton", "label": "Check OK", "action": "workflow.transition", "instanceId": "{{form.instanceId}}", "targetState": "PMT_CHECK_OK", "color": "primary"}, {"kind": "WorkflowActionButton", "label": "Camera Verification", "action": "workflow.transition", "instanceId": "{{form.instanceId}}", "targetState": "PMT_CAMERA_VERIFICATION", "color": "warning"}]}]}]}]}' WHERE pd.code='aria:pmt-weight-diff-check';
UPDATE page_version pv JOIN page_definition pd ON pd.current_version_id=pv.id SET pv.body_json='{"kind": "layout", "schemaVersion": 2, "entity": "GatePass", "dataSources": [{"id": "q", "kind": "rest", "method": "GET", "url": "/api/workflow/queue/PMT"}], "layout": [{"kind": "Grid", "columns": 12, "gap": 16, "children": [{"kind": "Section", "title": "Camera Verification — Over-tolerance vehicles", "span": 12, "subtitle": "Capture camera evidence; if issue found the vehicle can be released, else unload / recheck / reload.", "children": [{"kind": "WorkflowQueueList", "persona": "PMT", "dataSource": "q", "pageSize": 25, "cardFields": ["gpNumber", "vehicleNo", "flowVariant", "currentState"]}]}, {"kind": "Section", "title": "Record outcome", "span": 12, "children": [{"kind": "Form", "bindings": {"fields": [{"name": "gpNumber", "label": "Gate Pass # (pick one)", "type": "select", "required": true, "optionsSource": {"type": "entity", "entity": "GatePass", "lookupType": "gpNumbers", "valueField": "gp_number", "labelField": "gp_number"}, "onChangeFill": {"vehicle_no": "vehicle_no", "instanceId": "workflow_instance_id", "w1_weight_kg": "w1_weight_kg", "w2_weight_kg": "w2_weight_kg"}}, {"name": "vehicle_no", "label": "Vehicle", "type": "text", "readOnly": true}, {"name": "camera_photo", "label": "Camera Photo / Evidence", "type": "file"}, {"name": "issue_identified", "label": "Issue identified?", "type": "select", "required": true, "options": [{"label": "Yes — cause found, release", "value": "YES"}, {"label": "No — unload & recheck", "value": "NO"}]}, {"name": "variance_reason", "label": "Reason + shortage / excess qty", "type": "textarea"}]}, "children": [{"kind": "WorkflowActionButton", "label": "Release / To Manager", "action": "workflow.transition", "instanceId": "{{form.instanceId}}", "targetState": "PMT_CHECK_PENDING_MANAGER", "color": "primary"}]}]}]}]}' WHERE pd.code='aria:pmt-camera-verification';

-- dashboard body + publish
INSERT INTO page_version (page_id, version, body_json, status, published_at)
SELECT pd.id,1,'{"kind": "list", "schemaVersion": 2, "dataSource": {"type": "entity", "entity": "GatePass", "filter": {"field": "status", "op": "in", "value": ["LOADING_IN_PROGRESS", "DISPATCH_LOAD_ENTRY"]}}, "header": {"title": "Bay-wise Loading"}, "columns": [{"field": "loading_bay", "label": "Bay"}, {"field": "vehicle_no", "label": "Vehicle"}, {"field": "gp_number", "label": "GP #"}, {"field": "reference_no", "label": "Order ID"}, {"field": "flow_variant_code", "label": "Flow", "render": "badge"}, {"field": "processed_qty", "label": "Processed Qty"}, {"field": "remaining_qty", "label": "Remaining Qty"}, {"field": "status", "label": "Status", "render": "badge"}], "filters": [{"field": "loading_bay", "label": "Bay", "type": "text"}], "pagination": {"pageSize": 25}, "rowActions": [{"label": "📦 Order", "action": "page.open", "page": "aria:loading-order", "params": {"route": "row.route_id"}}]}','PUBLISHED',NOW() FROM page_definition pd WHERE pd.code='aria:loading-dashboard'
  AND NOT EXISTS (SELECT 1 FROM page_version pv WHERE pv.page_id=pd.id);
UPDATE page_definition pd SET current_version_id=(SELECT id FROM page_version WHERE page_id=pd.id ORDER BY version DESC LIMIT 1) WHERE pd.code='aria:loading-dashboard';
